# Every action exercises both individual text budgets and the full request envelope.
def utf8_boundary(action, field, original):
    if field=='secondary' and action=='django.migrations':
        base='/**/'
        prefix,suffix='/*','*/'
    elif field=='secondary' and action not in {'spring.config','django.urls','django.openapi'}:
        prefix,suffix='',''
    elif action in {'java.threads','java.dependencies','java.gc','django.migrations','django.checks','celery.report'} and field=='text':
        prefix,suffix=original+'\n#',''
    else:
        try:value=json.loads(original)
        except ValueError:
            # The sample configuration is YAML; a quoted synthetic field is valid YAML.
            prefix,suffix=original+'\nzz_padding: "','"'
        else:
            if isinstance(value,list):
                value[0]['zz_padding']='MARKER'
            else:value['zz_padding']='MARKER'
            prefix,suffix=json.dumps(value,ensure_ascii=False,separators=(',',':')).split('MARKER')
    count=8192-len((prefix+suffix).encode())
    return prefix+'中'*(count//3)+'a'*(count%3)+suffix

for action,text,secondary,checks in samples:
    for field in ['text','secondary']:
        original=text if field=='text' else secondary
        for kind in ['ascii','utf8']:
            padded=original+' '*(8192-len(original.encode())) if kind=='ascii' else utf8_boundary(action,field,original)
            assert len(padded.encode())==8192
            boundary=request(action,padded if field=='text' else text,padded if field=='secondary' else secondary)
            cases.append((action+'-'+field+'-'+kind+'-8192',boundary,checks,None))
            over=copy.deepcopy(boundary);over['input'][field]+=' '
            cases.append((action+'-'+field+'-'+kind+'-8193',over,None,'INPUT_TOO_LARGE'))
    basecase=request(action,text,secondary)
    data=json.dumps(basecase,ensure_ascii=False,separators=(',',':')).encode()
    cases.append((action+'-request-49152',data+b' '*(49152-len(data)),checks,None))
    cases.append((action+'-request-49153',data+b' '*(49153-len(data)),None,'INPUT_TOO_LARGE'))
    for level in ['envelope','input']:
        unknown=copy.deepcopy(basecase)
        (unknown if level=='envelope' else unknown['input'])['unexpected']=True
        cases.append((action+'-unknown-'+level,unknown,None,'INVALID_INPUT'))
    invalid=request(action,'not a report','not a report')
    if action=='spring.config':invalid['input']['text']='['
    cases.append((action+'-invalid-report',invalid,None,'INVALID_REPORT'))

